import{_ as r}from"./chunks/theme.Dz6sOhMe.js";import{_ as o,c as e,o as a,a4 as s}from"./chunks/framework.DZlzUqxb.js";const n="/wxme.jpg",b=JSON.parse('{"title":"关于作者","description":"","frontmatter":{},"headers":[],"relativePath":"me/index.md","filePath":"me/index.md","lastUpdated":1773330734000}'),p={name:"me/index.md"};function l(i,t,_,m,c,d){return a(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="关于作者" tabindex="-1">关于作者 <a class="header-anchor" href="#关于作者" aria-label="Permalink to &quot;关于作者&quot;">​</a></h1><p>大家好，我是陈老老老板！</p><p>起这个名字，是因为我想成为一个“老板”——而且是那种能坚持<strong>超级无敌长时间</strong>的老板（不是“超级老”的意思 😄），所以就叫“陈老老老板”！</p><p>我热爱编程，喜欢折腾各种好玩、好用的工具。做这个网站，就是希望把我的探索和经验分享出来，真正帮到大家。</p><p>如果想了解我的经历，可以看看我写的 <a href="./summary/2022.html">2022 年总结</a>（现在一看还是非常尬的...）。那一年我刚毕业，第一次开始写文章，那时候斗志昂扬，对未来充满计划与期待。 已经好几年没有再写过总结，没有了对下一年的计划与展望，希望 2026 年能有一个新的开始吧！</p><p>其实，做这个网站的想法在我心里已经很久了，但一直拖延、找借口、迟迟没有行动。<br> 这次，我给自己定下了一个明确的目标：<strong>2026 年 2 月 1 日正式上线！</strong><br> 我希望这一天能被记住——我甚至为这次行动起了个代号：<strong>“2 月 1 日攻势”</strong> 🎯 ， 哈哈哈 😄</p><p>最后，说说我最喜欢的漫画人物：<strong>查理·布朗</strong>。<br> 他的宠物是史努比，而他的朋友莱纳斯曾这样评价他：</p><blockquote><p>“<strong>我的老朋友查理·布朗，他从不放弃。</strong>”</p></blockquote><p>他还有一份难得的品质：</p><blockquote><p><strong>“如果他是你的朋友，那他就是你最好的朋友。只要是朋友的要求，哪怕再难办到，他也会拼尽全力去完成。他从不对朋友说‘不’，总是用最真诚的心，希望朋友开心。”</strong></p></blockquote><p>查理·布朗当棒球队长的战绩是 <strong>2 胜 930 败</strong>，但他从未因此放弃。<br> 我也希望能像他一样：<strong>永不言弃，真诚待人。</strong></p><hr><p>如果你：</p><ul><li>想交个朋友</li><li>需要技术帮助</li><li>想加群一起聊天</li><li>或有合作想法</li></ul><p>都欢迎加我微信或关注公众号 👇<br><img src="'+n+'" alt="我的微信" loading="lazy"><img src="'+r+'" alt="公众号" loading="lazy"></p>',15)])])}const f=o(p,[["render",l]]);export{b as __pageData,f as default};
